document.body.innerHTML = '<form id="f"><input id="email" value="taylor@brogram"></form>';
const form = document.getElementById('f');
form.addEventListener('submit', (e) => {
  e.preventDefault();
  const value = document.getElementById('email').value;
  console.log(value.includes('@') ? 'sending' : 'fix that email');
});
form.dispatchEvent(new Event('submit', { cancelable: true }));

document.body.innerHTML =
  '<form id="order"><input id="qty" value="0"><button>Buy</button></form>';
const form = document.getElementById('order');
form.addEventListener('submit', function (event) {
  event.preventDefault();
  const qty = Number(document.getElementById('qty').value);
  if (qty <= 0) {
    console.log('pick at least one');
    return;
  }
  console.log('ordered ' + qty);
});
form.dispatchEvent(new Event('submit', { cancelable: true }));

